SELECT	p."Registraèní èíslo projektu" ,
	sum(s.VYDAJESCHVAL) AS "Schválené ZV",
	r."Pøedpokládaná èástka VZ",
	p.czv,

	(case when r."Pøedpokládaná èástka VZ" <  2000001 then  50000
	     when r."Pøedpokládaná èástka VZ" <  5000001 then 100000
	     when r."Pøedpokládaná èástka VZ" < 10000001 then 150000
	     else 200000
	end) as "Max ZV na VØ"
	
FROM isum.v_bi_UmzPrjGG p 
INNER JOIN isum.V_BI_UMFSoupiskaDokladPRJ s on s.id_projekt=p.id
INNER JOIN isum.v_bi_UMFROZPolozky polozky ON polozky.id = id_polozka
LEFT JOIN (
SELECT rizeni.id_nositelvr,
       sum(rizeni.CASTKAPREDPOKLAD) "Pøedpokládaná èástka VZ"
FROM isum.v_bi_UMVVyberovaRizeni rizeni
WHERE rizeni.id_admstav = 325496760 -- schválená vz
GROUP BY rizeni.id_nositelvr ) r ON r.id_nositelvr = p.id

WHERE p."Registraèní èíslo projektu" is not null
AND p.id_vyzva = 348643343 -- výzva 01_18_183
AND p.id = 516332242
AND s."Èástka bez DPH pøipadající na" >0 -- nenulové doklady
AND polozky."Kód" in ('1.2.1.7','1.2.2.2')
